  ('tq-sb-building-a-complete-crud-rest-api-1', 'pt-sb-building-a-complete-crud-rest-api',
   $sb340$Which HTTP method and success status are normally used to create a resource in a CRUD API?$sb340$,
   $sb341$["GET and 200","POST and 201","PUT and 204","DELETE and 201"]$sb341$::jsonb,
   1, $sb342$Create uses POST, and a new item is reported with 201 Created.$sb342$, 1, 0),
  ('tq-sb-building-a-complete-crud-rest-api-2', 'pt-sb-building-a-complete-crud-rest-api',
   $sb343$In a layered CRUD API, where should the rule 'the title must not be empty' live?$sb343$,
   $sb344$["In the repository","In the service","In the pom.xml","In the main application class"]$sb344$::jsonb,
   1, $sb345$Business rules belong in the service, so every entry point gets them and the controller stays thin.$sb345$, 1, 1),
  ('tq-sb-building-a-complete-crud-rest-api-3', 'pt-sb-building-a-complete-crud-rest-api',
   $sb346$A DELETE for an existing book returns ResponseEntity.noContent().build(). What does the client receive?$sb346$,
   $sb347$["Status 200 with the deleted book","Status 204 with an empty body","Status 404 with a message","Status 201 with a Location header"]$sb347$::jsonb,
   1, $sb348$noContent() sets 204, and there is no body because the item is simply gone.$sb348$, 1, 2),
  ('tq-sb-building-a-complete-crud-rest-api-4', 'pt-sb-building-a-complete-crud-rest-api',
   $sb349$The service throws BookNotFoundException for id 7, and a @RestControllerAdvice maps it to 404 with the message 'Book 7 does not exist'. What does GET /api/books/7 return?$sb349$,
   $sb350$["Status 500 with a stack trace","Status 200 with an empty list","Status 404 with the message in the body","Status 400 with no body"]$sb350$::jsonb,
   2, $sb351$The handler turns the exception into a 404 reply that carries the message.$sb351$, 1, 3),
  ('tq-sb-building-a-complete-crud-rest-api-5', 'pt-sb-building-a-complete-crud-rest-api',
   $sb352$A PUT /api/books/99 for a missing book silently creates a new book. What is missing?$sb352$,
   $sb353$["A @RequestParam on the method","A check that the book exists, throwing a not-found error before saving","A second controller class","A different HTTP method"]$sb353$::jsonb,
   1, $sb354$Update must first confirm the item exists and answer 404 if it does not, instead of saving blindly.$sb354$, 1, 4)
on conflict (id) do update set
  question_text = excluded.question_text, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation,
  marks = excluded.marks, sort_order = excluded.sort_order
where (test_questions.question_text, test_questions.options, test_questions.correct_index,
       test_questions.explanation, test_questions.marks, test_questions.sort_order)
  is distinct from (excluded.question_text, excluded.options, excluded.correct_index,
       excluded.explanation, excluded.marks, excluded.sort_order);
delete from public.test_questions where test_id = 'pt-sb-building-a-complete-crud-rest-api'
  and id <> all (array['tq-sb-building-a-complete-crud-rest-api-1', 'tq-sb-building-a-complete-crud-rest-api-2', 'tq-sb-building-a-complete-crud-rest-api-3', 'tq-sb-building-a-complete-crud-rest-api-4', 'tq-sb-building-a-complete-crud-rest-api-5']);

-- ===========================================================================
-- VALIDATION — fail loudly if this batch did not land exactly.
-- ===========================================================================
do $val$
declare
  v_topics int; v_lessons int; v_practice int; v_tests int; v_questions int; v_web boolean; v_mob boolean;
begin
  select count(*) into v_topics from public.learning_topics where source_kind = 'spring_boot_tutorial' and source_ref in ($sb355$rest-api/spring-mvc-architecture$sb355$, $sb356$rest-api/controller-vs-rest-controller$sb356$, $sb357$rest-api/request-mapping$sb357$, $sb358$rest-api/get-post-put-delete-mapping$sb358$, $sb359$rest-api/path-variable$sb359$, $sb360$rest-api/request-param$sb360$, $sb361$rest-api/request-body$sb361$, $sb362$rest-api/responseentity$sb362$, $sb363$rest-api/http-status-codes-in-spring-boot$sb363$, $sb364$rest-api/dto-pattern$sb364$, $sb365$rest-api/building-a-complete-crud-rest-api$sb365$);
  if v_topics <> 11 then raise exception 'validation: expected 11 topics, found %', v_topics; end if;
  select count(*) filter (where c.metadata ->> 'block' = 'lesson'), count(*) filter (where c.metadata ->> 'block' = 'practice')
    into v_lessons, v_practice
    from public.learning_contents c join public.learning_topics t on t.id = c.topic_id
   where c.metadata ->> 'source' = 'spring_boot_seed' and t.source_kind = 'spring_boot_tutorial' and t.source_ref in ($sb355$rest-api/spring-mvc-architecture$sb355$, $sb356$rest-api/controller-vs-rest-controller$sb356$, $sb357$rest-api/request-mapping$sb357$, $sb358$rest-api/get-post-put-delete-mapping$sb358$, $sb359$rest-api/path-variable$sb359$, $sb360$rest-api/request-param$sb360$, $sb361$rest-api/request-body$sb361$, $sb362$rest-api/responseentity$sb362$, $sb363$rest-api/http-status-codes-in-spring-boot$sb363$, $sb364$rest-api/dto-pattern$sb364$, $sb365$rest-api/building-a-complete-crud-rest-api$sb365$);
  if v_lessons <> 11 then raise exception 'validation: expected 11 lesson blocks, found %', v_lessons; end if;
  if v_practice <> 11 then raise exception 'validation: expected 11 practice blocks, found %', v_practice; end if;
  select count(*) into v_tests from public.practice_tests where id in ('pt-sb-spring-mvc-architecture', 'pt-sb-controller-vs-rest-controller', 'pt-sb-request-mapping', 'pt-sb-get-post-put-delete-mapping', 'pt-sb-path-variable', 'pt-sb-request-param', 'pt-sb-request-body', 'pt-sb-responseentity', 'pt-sb-http-status-codes-in-spring-boot', 'pt-sb-dto-pattern', 'pt-sb-building-a-complete-crud-rest-api') and learning_topic_id is not null;
  if v_tests <> 11 then raise exception 'validation: expected 11 linked mock tests, found %', v_tests; end if;
  select count(*) into v_questions from public.test_questions where test_id in ('pt-sb-spring-mvc-architecture', 'pt-sb-controller-vs-rest-controller', 'pt-sb-request-mapping', 'pt-sb-get-post-put-delete-mapping', 'pt-sb-path-variable', 'pt-sb-request-param', 'pt-sb-request-body', 'pt-sb-responseentity', 'pt-sb-http-status-codes-in-spring-boot', 'pt-sb-dto-pattern', 'pt-sb-building-a-complete-crud-rest-api');
  if v_questions <> 55 then raise exception 'validation: expected 55 MCQs, found %', v_questions; end if;
  select show_on_website, show_on_mobile into v_web, v_mob from (select id, show_on_website, show_on_mobile from public.learning_grids where lower(slug) = 'spring-boot-tutorial' and source_kind = 'seed' and source_ref = 'spring_boot_tutorial') g;
  raise notice '0129/101 OK: Spring Boot Tutorial batch 06: % topics, % lesson blocks, % practice blocks, % tests, % MCQs. Grid visible on website=%, mobile=%.',
    v_topics, v_lessons, v_practice, v_tests, v_questions, v_web, v_mob;
end
$val$;

notify pgrst, 'reload schema';
